<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { enterpriseInternshipApi } from '../services/enterpriseInternshipApi'
import { useEnterpriseContextStore } from '../stores/enterpriseContext'
const route=useRoute(),router=useRouter(),context=useEnterpriseContextStore(),id=computed(()=>route.params.id),loading=ref(Boolean(route.params.id)),saving=ref(false),withdrawing=ref(false),error=ref(''),positionStatus=ref(route.params.id?'':'DRAFT')
const form=reactive({title:'',category:'',headcount:null,workLocation:'',workAddress:'',majorRequirement:'',gradeRequirement:'',mentorContactId:null,workContent:'',remark:'',dailyHours:null,weeklyHours:null,shiftType:'DAY',nightShift:false,overtimeAllowed:false,restDaysPerWeek:null,remunerationType:'MONTHLY',remunerationAmount:null,remunerationCycle:'MONTHLY',salaryRange:'',subsidy:'',accommodationProvided:false,mealProvided:false,hazardousFlag:false,specialEquipment:'',prohibitedReason:''})
const editableKeys=Object.keys(form)
const statusLabels={DRAFT:'草稿',PENDING:'待学校审核',PUBLISHED:'已发布',OFFLINE:'已下线',SUSPENDED:'已暂停',FULL:'已招满',RISK:'风险',ARCHIVED:'已归档'}
const statusText=computed(()=>statusLabels[positionStatus.value]||positionStatus.value||'加载中')
const canEdit=computed(()=>context.recruitmentWritable && (!id.value || positionStatus.value==='DRAFT'))
const canWithdraw=computed(()=>context.recruitmentWritable && Boolean(id.value) && positionStatus.value==='PENDING')
// State contract: PENDING 必须先撤回再修改；企业不能直接 PUBLISH。
const checks=computed(()=>[{ok:Boolean(form.title),text:'岗位名称已填写'},{ok:Number(form.headcount)>0,text:'招聘人数已填写'},{ok:Boolean(form.workContent),text:'工作内容已填写'},{ok:Number(form.weeklyHours)>0,text:'每周工时已填写'},{ok:Boolean(form.salaryRange||form.remunerationAmount),text:'报酬条件完整'},{ok:!form.nightShift,text:form.nightShift?'夜班岗位需学校进一步核验':'无夜班特殊核验'}])
onMounted(async()=>{if(!id.value)return;try{const data=await enterpriseInternshipApi.position(id.value)||{};positionStatus.value=data.status||'';for(const key of editableKeys)if(data[key]!==undefined)form[key]=data[key]}catch(e){error.value=e.message||'岗位加载失败'}finally{loading.value=false}})
async function withdraw(){if(!canWithdraw.value)return;withdrawing.value=true;error.value='';try{const data=await enterpriseInternshipApi.withdrawPosition(id.value);positionStatus.value=data?.status||'DRAFT'}catch(e){error.value=e.message||'撤回岗位失败'}finally{withdrawing.value=false}}
async function save(submit=false){if(!canEdit.value){error.value=positionStatus.value==='PENDING'?'岗位正在学校审核中，请先撤回到草稿后再修改':'当前岗位状态不可由企业直接修改';return}saving.value=true;error.value='';try{let pid=id.value;if(pid) await enterpriseInternshipApi.updatePosition(pid,{...form});else{const created=await enterpriseInternshipApi.createPosition({...form});pid=created?.id}if(submit){if(!pid)throw new Error('岗位保存后未返回有效编号');await enterpriseInternshipApi.submitPosition(pid)}await router.push('/positions')}catch(e){error.value=e.message||'岗位保存失败'}finally{saving.value=false}}
</script>
<template><section class="ep-page"><div class="ep-page-head"><div><h1 class="ep-title">{{ id?'岗位详情':'创建实习岗位' }}</h1><p class="ep-subtitle">草稿可编辑；待学校审核的岗位需先撤回后再修改；发布结果由学校统一审核。</p></div><span v-if="id" class="ep-tag" :class="{warn:positionStatus==='PENDING',ok:positionStatus==='PUBLISHED'}">{{ statusText }}</span></div><div v-if="!context.recruitmentWritable" class="history-note">当前招聘季不可编辑：页面保留岗位信息查看，企业提交和修改操作已关闭。</div><div v-else-if="positionStatus==='PENDING'" class="history-note">岗位正在学校审核中。为避免审核期间信息变化，当前仅可查看；需要修改请先撤回到草稿。</div><div v-else-if="id && positionStatus!=='DRAFT'" class="history-note">当前岗位状态为“{{ statusText }}”，本页仅可查看。企业不能直接修改为已发布状态。</div><div v-if="error" class="ep-error">{{ error }}</div><div v-if="loading" class="ep-card ep-empty">正在加载岗位…</div><div v-else class="form-layout"><div class="sections"><section class="ep-card panel"><h2>1. 基本信息</h2><div class="fields"><label>岗位名称 *<input v-model="form.title" class="ep-input" :disabled="!canEdit"></label><label>岗位类别<input v-model="form.category" class="ep-input" :disabled="!canEdit"></label><label>招聘人数 *<input v-model.number="form.headcount" type="number" min="1" class="ep-input" :disabled="!canEdit"></label><label>工作城市 / 地区 *<input v-model="form.workLocation" class="ep-input" :disabled="!canEdit"></label><label class="wide">详细工作地址 *<input v-model="form.workAddress" class="ep-input" :disabled="!canEdit"></label><label>专业要求<input v-model="form.majorRequirement" class="ep-input" :disabled="!canEdit"></label><label>年级要求<input v-model="form.gradeRequirement" class="ep-input" :disabled="!canEdit"></label></div></section><section class="ep-card panel"><h2>2. 岗位职责 / 要求</h2><label>工作内容 *<textarea v-model="form.workContent" class="ep-textarea" rows="6" :disabled="!canEdit" /></label><label>补充说明<textarea v-model="form.remark" class="ep-textarea" rows="3" :disabled="!canEdit" /></label></section><section class="ep-card panel"><h2>3. 工作安排</h2><div class="fields"><label>每日工时 *<input v-model.number="form.dailyHours" type="number" min="0" max="24" class="ep-input" :disabled="!canEdit"></label><label>每周工时 *<input v-model.number="form.weeklyHours" type="number" min="0" class="ep-input" :disabled="!canEdit"></label><label>班次<select v-model="form.shiftType" class="ep-select" :disabled="!canEdit"><option value="DAY">白班</option><option value="ROTATING">轮班</option></select></label><label>每周休息天数 *<input v-model.number="form.restDaysPerWeek" type="number" min="0" max="7" class="ep-input" :disabled="!canEdit"></label><label class="check"><input v-model="form.nightShift" type="checkbox" :disabled="!canEdit">存在夜班</label><label class="check"><input v-model="form.overtimeAllowed" type="checkbox" :disabled="!canEdit">允许加班</label></div></section><section class="ep-card panel"><h2>4. 薪酬福利</h2><div class="fields"><label>报酬类型<select v-model="form.remunerationType" class="ep-select" :disabled="!canEdit"><option value="MONTHLY">月薪</option><option value="DAILY">日薪</option><option value="HOURLY">时薪</option></select></label><label>报酬金额<input v-model.number="form.remunerationAmount" type="number" min="0" class="ep-input" :disabled="!canEdit"></label><label>发放周期<select v-model="form.remunerationCycle" class="ep-select" :disabled="!canEdit"><option value="MONTHLY">每月</option><option value="WEEKLY">每周</option><option value="ONCE">一次性</option></select></label><label>薪资展示<input v-model="form.salaryRange" class="ep-input" placeholder="如 3500-4500/月" :disabled="!canEdit"></label><label>补贴<input v-model="form.subsidy" class="ep-input" :disabled="!canEdit"></label><label class="check"><input v-model="form.accommodationProvided" type="checkbox" :disabled="!canEdit">提供住宿</label><label class="check"><input v-model="form.mealProvided" type="checkbox" :disabled="!canEdit">提供餐食</label></div></section><section class="ep-card panel"><h2>5. 安全权益</h2><label class="check"><input v-model="form.hazardousFlag" type="checkbox" :disabled="!canEdit">危险 / 特殊岗位</label><label>特殊设备<input v-model="form.specialEquipment" class="ep-input" :disabled="!canEdit"></label><label>禁止安排说明<textarea v-model="form.prohibitedReason" class="ep-textarea" rows="3" :disabled="!canEdit" /></label></section></div><aside class="ep-card preview"><h2 class="ep-section-title">提交学校审核前检查</h2><div v-for="check in checks" :key="check.text" class="check-row" :class="check.ok?'ok':'warn'">{{ check.ok?'✓':'!' }} {{ check.text }}</div><p class="ep-muted">这里只做提交前检查；岗位最终是否发布，以学校审核结果为准。</p></aside></div><div class="actions"><button v-if="canWithdraw" class="ep-btn" :disabled="withdrawing" @click="withdraw">{{ withdrawing?'撤回中…':'撤回到草稿修改' }}</button><template v-if="canEdit"><button class="ep-btn" :disabled="saving" @click="save(false)">保存草稿</button><button class="ep-btn ep-btn-primary" :disabled="saving" @click="save(true)">提交学校审核</button></template></div></section></template>
<style scoped>.history-note{padding:12px 14px;margin-bottom:14px;background:var(--warn-bg);color:var(--warn-fg);border-radius:8px;font-size:13px}.form-layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:16px;align-items:start}.sections{display:grid;gap:14px}.panel,.preview{padding:20px}.panel h2{font-size:16px;margin:0 0 16px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}label{display:flex;flex-direction:column;gap:7px;font-size:13px;color:var(--t2);margin-bottom:13px}.fields label{margin-bottom:0}.wide{grid-column:1/-1}.check{flex-direction:row;align-items:center;min-height:40px}.ep-input,.ep-select,.ep-textarea{width:100%}.preview{position:sticky;top:78px}.check-row{padding:9px 0;border-bottom:1px solid var(--line);font-size:13px}.check-row.ok{color:var(--ok-fg)}.check-row.warn{color:var(--warn-fg)}.actions{display:flex;justify-content:flex-end;gap:10px;position:sticky;bottom:0;background:linear-gradient(transparent,var(--page) 30%);padding:24px 0 6px}@media(max-width:1000px){.form-layout{grid-template-columns:1fr}.preview{position:static}}@media(max-width:700px){.fields{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
